(()=>{'use strict';const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fit=()=>document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));fit();addEventListener('resize',fit);function clock(){$('clock').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());}clock();setInterval(clock,1000);let saved=null;const field=(label,name,required=false,value='',placeholder='')=>`<label class="create-field"><span>${label}${required?'<i>*</i>':''}</span><input name="${name}" value="${esc(value)}" placeholder="${placeholder}" ${required?'required':''} maxlength="80"></label>`;const select=(label,name,values)=>`<label class="create-field"><span>${label}</span><select name="${name}">${values.map(v=>`<option>${v}</option>`).join('')}</select></label>`;const section=(title,body,c='')=>`<section class="panel ${c}"><div class="panel-title"><h2>${title}</h2></div><div class="create-section-body">${body}</div></section>`;
$('suite-main').innerHTML=`<div class="create-order-layout"><form id="create-order-form" class="create-order-form"><div class="suite-toolbar"><div><h2>创建维修工单</h2><small>设备故障与维修任务登记</small></div><span class="required-note"><i>*</i> 为必填项</span></div>${section('工单基本信息',`<div class="create-grid four">${field('工单编号','number',true,'KD096','输入工单编号')}${select('工单类型','type',['一般性维修','计划性维修','外委性维修'])}${select('优先级','priority',['一般','紧急'])}${select('工单状态','status',['待处理','上报','待观察','待验收','待关闭','关闭'])}</div><p class="create-section-note">通过优先级区分任务处理顺序，状态用于跟进维修进度。</p>`,'create-basic')}${section('故障与设备信息',`<label class="create-field create-description"><span>工单描述<i>*</i></span><textarea name="description" maxlength="300" placeholder="描述需要处理的设备故障" required></textarea><span class="description-count"><b id="description-count">0</b> / 300</span></label><div class="create-grid three">${field('关联问题','issue',false,'','输入关联问题')}${field('设备','device',true,'','输入设备名称')}${field('部门','department',true,'','输入所属部门')}</div>`,'create-fault')}${section('计划与责任人员',`<div class="create-grid two"><label class="create-field"><span>计划开始</span><input name="start" type="datetime-local" step="1"></label><label class="create-field"><span>计划结束</span><input name="end" type="datetime-local" step="1"></label>${field('负责人','owner',false,'','输入负责人姓名')}${field('处理人','handler',false,'','输入处理人姓名')}</div>`,'create-assignment')}<div class="create-actions"><span id="save-feedback">填写工单信息后保存</span><div><button class="suite-button" type="reset">重置内容</button><button class="suite-button primary" type="submit">保存工单</button></div></div></form><aside class="create-order-side">${section('工单摘要',`<div class="create-preview-heading"><span>工单编号</span><h2 id="preview-number">KD096</h2><b id="preview-saved">尚未保存</b></div><div class="preview-tags"><span id="preview-priority">一般</span><span id="preview-status">待处理</span></div><div class="preview-description"><span>工单描述</span><p id="preview-description">等待填写故障描述</p></div><dl class="create-preview-fields">${[['type','工单类型','一般性维修'],['device','设备','未填写'],['department','部门','未填写'],['owner','负责人','未填写'],['handler','处理人','未填写'],['start','计划开始','未设置'],['end','计划结束','未设置']].map(([n,l,v])=>`<div><dt>${l}</dt><dd id="preview-${n}">${v}</dd></div>`).join('')}</dl><div class="create-preview-tail"><i class="live-dot"></i><span>摘要随填写内容同步更新</span></div>`,'create-preview-panel')}</aside></div>`;
const form=$('create-order-form');function summary(){const v=Object.fromEntries(new FormData(form));$('preview-number').textContent=v.number.trim()||'待编号';$('preview-priority').textContent=v.priority;$('preview-priority').classList.toggle('urgent',v.priority==='紧急');$('preview-status').textContent=v.status;$('preview-description').textContent=v.description.trim()||'等待填写故障描述';$('description-count').textContent=v.description.length;for(const n of ['type','device','department','owner','handler','start','end'])$('preview-'+n).textContent=(v[n]||'').replace('T',' ')||(n==='start'||n==='end'?'未设置':'未填写');$('preview-saved').textContent='尚未保存';$('preview-saved').classList.remove('saved');$('save-feedback').textContent='填写工单信息后保存';form.querySelector('[name="number"]').setCustomValidity('');form.querySelector('[name="end"]').setCustomValidity('');}
form.addEventListener('input',summary);form.addEventListener('change',summary);form.addEventListener('reset',()=>{saved=null;setTimeout(summary,0);});let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
form.addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));for(const n of ['number','description','device','department'])if(!v[n].trim()){toast('请填写完整的工单编号、描述、设备与部门');form.querySelector('[name="'+n+'"]').focus();return;}if(/^KD0(?:0[1-9]|[1-8]\d|9[0-5])$/.test(v.number.trim())){toast('该工单编号已存在，请使用其他编号');form.querySelector('[name="number"]').setCustomValidity('工单编号已存在');return;}if(v.start&&v.end&&v.end<v.start){toast('计划结束时间不能早于开始时间');form.querySelector('[name="end"]').setCustomValidity('计划结束时间不能早于开始时间');return;}saved=Object.fromEntries(Object.entries(v).map(([k,value])=>[k,String(value).trim()]));$('preview-saved').textContent='已保存当前记录';$('preview-saved').classList.add('saved');$('save-feedback').textContent='工单 '+saved.number+' 已保留在当前页面';toast('工单已保存至当前页面');});
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('请在独立页面中使用浏览器全屏。');}};})();
